    <div class="form-grid two"><div class="field field-step"><label><i>09</i> Lieu</label><select id="bPlace">${PLACES.map(x=>`<option ${draft.place===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field field-step"><label><i>10</i> Matériel</label><button class="select-button" type="button" data-equipment>${draft.equipment.length?`${draft.equipment.length} sélectionné(s)`:'Choisir le matériel'}</button></div></div>
