function filteredPrograms(){let q=programFilter.q||'',family=programFilter.family||'Tous';return TEMPLATES.filter(t=>(family==='Tous'||t.family===family)&&(!q||normalize(t.title+' '+t.category+' '+t.focus+' '+t.format+' '+t.family+' '+(t.equipment||[]).join(' ')).includes(normalize(q))))}
