/* ========================= FAFATRAINING =========================
   Intelligence de programmation + UX progressive + Resource Planner +
   planification jour/semaine + Studio Social multi-templates.
===================================================================== */
const V93_GOAL_PATTERNS={
  force:['push','pull','squat','hinge','core'],
  hypertrophie:['push','pull','squat','hinge','lunge','core'],
  endurance:['cardio','squat','push','pull','core'],
  performance:['power','squat','hinge','push','pull','carry','core'],
  general:['squat','hinge','push','pull','core','cardio']
};
function parseNumV93(v,fallback=0){let n=Number(v);return Number.isFinite(n)?n:fallback}
function patternOfV93(e){let q=normalize(`${e?.pattern||''} ${e?.name||''} ${e?.family||''} ${e?.group||''}`);if(/mobil|stretch|souples|etirement/.test(q))return'mobility';if(/boxe|jab|cross|crochet|uppercut|shadow|sac/.test(q))return'combat';if(/squat/.test(q))return'squat';if(/hinge|souleve|deadlift|good morning|hip thrust/.test(q))return'hinge';if(/fente|lunge|split squat|step.?up/.test(q))return'lunge';if(/pull|row|tirage|traction|curl/.test(q))return'pull';if(/push|developpe|pompe|dip|press|extension triceps/.test(q))return'push';if(/carry|farmer|suitcase/.test(q))return'carry';if(/jump|saut|bond|plyo|slam|throw/.test(q))return'power';if(/core|gainage|planche|plank|dead bug|bird dog|hollow|abdo/.test(q))return'core';if(/run|course|sprint|cardio|bike|rameur|ski erg|burpee|jumping jack/.test(q))return'cardio';return'general'}
function externalEquipmentV93(e){return (e?.equipment||[]).filter(q=>!['poids du corps','sol','extérieur','terrain','petit espace'].includes(normalize(q)))}
function equipmentMatch(e){if(!draft.equipment.length)return true;let have=draft.equipment.map(normalize),req=externalEquipmentV93(e).map(normalize);return !req.length||req.every(q=>have.includes(q))}
function goalTypeV93(){let q=normalize(`${draft.goal} ${draft.subgoal}`);if(q.includes('force')&&!q.includes('endurance'))return'force';if(q.includes('hypertroph')||q.includes('muscle'))return'hypertrophie';if(q.includes('endurance')||q.includes('cardio')||q.includes('vma')||q.includes('vo2'))return'endurance';if(q.includes('puissance')||q.includes('explos')||q.includes('performance'))return'performance';return'general'}
function sessionMainItemsV93(s){return (s?.blocks||[]).filter(b=>/principal|atelier|libre|force|circuit|travail/i.test(b.label)).flatMap(b=>b.items||[])}
function setsOfV93(it){let n=parseInt(it?.rx?.sets,10);return Number.isFinite(n)&&n>0?n:1}
function completedLoadV93(clientId,days=7){let now=Date.now(),cut=now-days*864e5,out={muscles:{},patterns:{},total:0,sessions:0,lastAt:null};if(!clientId)return out;for(let s of state.sessions||[]){if(s.clientId!==clientId||s.status!=='completed')continue;let t=new Date(s.completedAt||s.date).getTime();if(!Number.isFinite(t)||t<cut)continue;let rpe=parseNumV93(s.completion?.rpe,7),factor=Math.max(.55,Math.min(1.25,rpe/8));out.sessions++;out.lastAt=Math.max(out.lastAt||0,t);for(let it of sessionMainItemsV93(s)){let sets=setsOfV93(it),p=patternOfV93(it),load=sets*factor;out.patterns[p]=(out.patterns[p]||0)+load;let ms=it.muscles?.length?it.muscles:['global'];for(let m of ms)out.muscles[m]=(out.muscles[m]||0)+load/ms.length;out.total+=load}}return out}
function topEntriesV93(obj,n=3){return Object.entries(obj||{}).sort((a,b)=>b[1]-a[1]).slice(0,n)}
function fatiguePenaltyV93(e,load){let p=patternOfV93(e),pen=(load.patterns[p]||0)*2.2;for(let m of e.muscles||[])pen+=(load.muscles[m]||0)*1.25;return Math.min(42,pen)}
function placeMatchV93(e){let p=(e.places||[]).map(normalize),wanted=normalize(draft.place);if(!p.length||!wanted)return 0;return p.includes(wanted)?9:-28}
function scoreExercise(e,i){let s=100-i*.015;if(zoneMatch(e,draft.zone))s+=16;if(supportsLevel(e,draft.level))s+=9;if((e.equipment||[]).includes('poids du corps'))s+=2;s+=placeMatchV93(e);let load=completedLoadV93(draft.clientId,4);s-=fatiguePenaltyV93(e,load);let recent=state.sessions.filter(x=>x.clientId&&x.clientId===draft.clientId).slice(0,5).flatMap(x=>sessionMainItemsV93(x)),recentGroups=new Set(recent.map(x=>x.progressionGroup||x.name));if(recentGroups.has(e.progressionGroup||e.name))s-=20;let c=state.clients.find(x=>x.id===draft.clientId);if(c?.likedExercises&&normalize(c.likedExercises).includes(normalize(e.name)))s+=14;if(c?.avoidExercises&&normalize(c.avoidExercises).includes(normalize(e.name)))s-=120;let con=normalize(draft.constraints);if((con.includes('pas de saut')||con.includes('sans saut'))&&patternOfV93(e)==='power')s-=120;if((con.includes('genou')||con.includes('knee'))&&/jump|saut|bond/.test(normalize(e.name)))s-=30;return s}
function balanceBonusV93(e,selected){let p=patternOfV93(e),counts={};for(let x of selected){let k=patternOfV93(x);counts[k]=(counts[k]||0)+1}let bonus=0;if(p==='pull'&&(counts.push||0)>(counts.pull||0))bonus+=15;if(p==='push'&&(counts.pull||0)>(counts.push||0)+1)bonus+=10;if((p==='squat'||p==='hinge')&&!selected.some(x=>patternOfV93(x)===p))bonus+=13;if(p==='core'&&!selected.some(x=>patternOfV93(x)==='core'))bonus+=8;if(p==='power'&&goalTypeV93()==='performance'&&!selected.some(x=>patternOfV93(x)==='power'))bonus+=12;let muscleCounts={};for(let x of selected)for(let m of x.muscles||[])muscleCounts[m]=(muscleCounts[m]||0)+1;for(let m of e.muscles||[])bonus-=Math.max(0,(muscleCounts[m]||0)-1)*5;return bonus}
function resourceDemandPenaltyV93(e,selected){if(draft.mode!=='group'||!Object.keys(draft.equipmentQty||{}).length)return 0;let per=Math.ceil(draft.people/draft.stations),pen=0;for(let eq of e.equipment||[]){let n=normalize(eq);if(['poids du corps','sol','exterieur','terrain','tapis'].includes(n))continue;let have=Object.entries(draft.equipmentQty||{}).find(([k])=>normalize(k)===n)?.[1];if(have==null)continue;let same=selected.filter(x=>(x.equipment||[]).some(q=>normalize(q)===n)).length,need=(same+1)*per;if(need>have)pen+=55+(need-have)*8}return pen}
function balancedSelectV93(pool,n){let remaining=pool.slice(0,Math.max(100,n*15)),selected=[],seen=new Set();while(selected.length<n&&remaining.length){let best=-1,bestScore=-1e9;for(let i=0;i<remaining.length;i++){let e=remaining[i].e||remaining[i],base=remaining[i].s??scoreExercise(e,i),pg=e.progressionGroup||e.name;if(seen.has(pg)&&selected.length<n-2)base-=30;let score=base+balanceBonusV93(e,selected)-resourceDemandPenaltyV93(e,selected);if(score>bestScore){bestScore=score;best=i}}let item=remaining.splice(best,1)[0],e=item.e||item;selected.push(e);seen.add(e.progressionGroup||e.name)}return selected}
function enforceCoverageV93(selected,scored,n){if(draft.zone!=='Corps entier')return selected;let wanted=V93_GOAL_PATTERNS[goalTypeV93()]||V93_GOAL_PATTERNS.general,out=selected.slice(),present=()=>new Set(out.map(patternOfV93));for(let p of wanted){if(present().has(p))continue;let cand=scored.map(x=>x.e||x).find(e=>patternOfV93(e)===p&&!out.some(x=>x.id===e.id));if(!cand)continue;let counts={};out.forEach(x=>counts[patternOfV93(x)]=(counts[patternOfV93(x)]||0)+1);let ri=out.findIndex(x=>!wanted.includes(patternOfV93(x))||counts[patternOfV93(x)]>1);if(ri>=0)out[ri]=cand;else if(out.length<n)out.push(cand);else continue}return out.slice(0,n)}
function orderMainV93(items){let priority={power:1,squat:2,hinge:2,push:3,pull:3,lunge:4,carry:5,core:6,cardio:7,combat:4,general:5,mobility:8};return items.map((e,i)=>({e,i,p:priority[patternOfV93(e)]||5,d:e.difficulty||2})).sort((a,b)=>a.p-b.p||b.d-a.d||a.i-b.i).map(x=>x.e)}
function rxForExerciseV93(e,index=0){let rx={...rxFor()},type=goalTypeV93(),p=patternOfV93(e),pct=type==='force'?78:type==='hypertrophie'?68:type==='performance'&&['power','squat','hinge','push','pull'].includes(p)?55:null;if(type==='force'&&draft.level==='Avancé')pct=82;if(type==='hypertrophie'&&draft.level==='Avancé')pct=72;if(p==='core'||p==='cardio'||p==='mobility'||p==='combat')pct=null;let load=completedLoadV93(draft.clientId,4),fat=fatiguePenaltyV93(e,load);if(fat>26){rx.sets=Math.max(2,parseNumV93(rx.sets,3)-1);if(pct)pct=Math.max(45,pct-7);rx.coach=`${rx.coach} · fatigue locale récente : volume réduit`}if(pct)rx.percent=pct;rx.tempo=type==='hypertrophie'?'3-1-1':type==='force'?'2-1-X':'contrôlé';rx.pattern=p;return rx}
function resourcePlanV93(main){if(draft.mode!=='group')return null;let per=Math.ceil(draft.people/draft.stations),demand={},stations=[];main.slice(0,draft.stations).forEach((it,i)=>{let eqs=(it.equipment||[]).filter(q=>!['poids du corps','sol','extérieur','terrain'].includes(normalize(q)));stations.push({station:i+1,name:it.name,equipment:eqs});for(let eq of eqs)demand[eq]=(demand[eq]||0)+per});let conflicts=[];for(let [eq,need] of Object.entries(demand)){let entry=Object.entries(draft.equipmentQty||{}).find(([k])=>normalize(k)===normalize(eq)),have=entry?.[1];if(have!=null&&need>have)conflicts.push(`${eq} : ${need} nécessaires simultanément / ${have} disponibles`)}let rotations=Array.from({length:draft.stations},(_,r)=>stations.map((st,i)=>({group:i+1,station:((i+r)%draft.stations)+1})));return {perStation:per,demand,conflicts,stations,rotations}}
function sessionIntelligenceV93(main){let patterns={},muscles={};for(let it of main){let sets=setsOfV93(it),p=patternOfV93(it);patterns[p]=(patterns[p]||0)+sets;for(let m of it.muscles||[])muscles[m]=(muscles[m]||0)+sets}let push=patterns.push||0,pull=patterns.pull||0,squat=patterns.squat||0,hinge=patterns.hinge||0;return {patterns,muscles,pushPull:`${push}:${pull}`,squatHinge:`${squat}:${hinge}`,topMuscles:topEntriesV93(muscles,4)}}
function qualityCheck(blocks){let items=blocks.flatMap(b=>b.items),warnings=[],names=items.map(x=>normalize(x.name)),dup=names.length-new Set(names).size;if(dup)warnings.push(`${dup} doublon(s) détecté(s)`);let main=blocks.find(b=>/principal|atelier|libre/i.test(b.label))?.items||[];if(main.length<4)warnings.push('Bloc principal trop court');let intel=sessionIntelligenceV93(main),push=intel.patterns.push||0,pull=intel.patterns.pull||0;if(draft.zone==='Corps entier'&&push>0&&pull===0)warnings.push('Full Body sans tirage : ajoute un pattern Pull');if(draft.zone==='Corps entier'&&pull>0&&push===0)warnings.push('Full Body sans poussée : ajoute un pattern Push');if(push&&pull&&Math.max(push,pull)>Math.min(push,pull)*2.25)warnings.push(`Ratio poussée/tirage déséquilibré (${push}:${pull})`);let sq=intel.patterns.squat||0,hi=intel.patterns.hinge||0;if(draft.zone==='Corps entier'&&sq>0&&hi===0)warnings.push('Dominante squat sans charnière de hanches');for(let [m,v] of Object.entries(intel.muscles)){if(v>18)warnings.push(`${m} : volume élevé sur la séance (${Math.round(v)} séries estimées)`)}let estimated=draft.mode==='group'?Math.round((draft.work+draft.transition)*draft.stations*draft.rounds/60)+(Number(state.coach.defaultWarmup)||8)+(Number(state.coach.defaultCooldown)||5):draft.duration;if(draft.mode==='group'){if(draft.people<draft.stations)warnings.push('Plus d’ateliers que de participants');if(draft.people%draft.stations!==0)warnings.push(`Répartition non exacte : ${Math.ceil(draft.people/draft.stations)} pers. sur certains ateliers`);let rp=resourcePlanV93(main);if(rp?.conflicts?.length)warnings.push(...rp.conflicts.map(x=>`Conflit matériel simultané · ${x}`))}if(draft.equipment.length){for(let it of main){let req=externalEquipmentV93(it),missing=req.filter(q=>!draft.equipment.map(normalize).includes(normalize(q)));if(missing.length)warnings.push(`${it.name} : matériel non sélectionné (${missing.join(', ')})`)}}let recent=completedLoadV93(draft.clientId,4);for(let [m,v] of topEntriesV93(recent.muscles,2)){if(v>9&&intel.muscles[m]>8)warnings.push(`${m} déjà fortement sollicité récemment : recontrôle récupération / volume`)}return {ok:!warnings.length,warnings,duration:draft.duration,estimatedDuration:estimated,checkedAt:new Date().toISOString(),intelligence:intel}}
function buildSession(){syncDraft();if(draft.auto&&($('#bMethod')?.value==='FAFA choisit'||!$('#bMethod'))){let ms=methodsFor(draft.universe);draft.method=ms.includes('Séries classiques')&&goalTypeV93()==='force'?'Séries classiques':(ms.includes('Circuit Training')?'Circuit Training':ms[0]||'Séries classiques')}let pool=EX.filter(e=>supportsLevel(e,draft.level)&&universeMatch(e,draft.universe)&&equipmentMatch(e));let zonePool=pool.filter(e=>zoneMatch(e,draft.zone));if(zonePool.length>=6)pool=zonePool;let avoid=normalize(draft.constraints||'');pool=pool.filter(e=>!avoid||!String(e.name).split(/\s+/).some(w=>w.length>5&&avoid.includes(normalize(w))));let scored=pool.map((e,i)=>({e,s:scoreExercise(e,i)})).sort((a,b)=>b.s-a.s);let n=draft.mode==='group'?draft.stations:(draft.duration<=30?5:draft.duration<=45?7:draft.duration<=60?9:10),selected=balancedSelectV93(scored,n);selected=enforceCoverageV93(selected,scored,n);selected=orderMainV93(selected);if(selected.length<Math.min(5,n)){toast('Peu de mouvements correspondent exactement : élargis le matériel, le lieu ou la zone.');return}let warmPool=EX.filter(e=>supportsLevel(e,'Débutant')&&(patternOfV93(e)==='mobility'||patternOfV93(e)==='cardio'));let warm=warmPool.slice(0,Math.min(3,Math.max(2,Math.round(draft.duration/25)))),mixed=draft.mode==='group'&&draft.mixed;let blocks=[{label:'Échauffement',items:warm.map(e=>sessionItem(e,{sets:1,reps:'30–45 s / 8–10 reps',rest:'15–20 s',simple:'Progressif',coach:'RPE 3–4'}))},{label:draft.mode==='group'?'Ateliers / bloc principal':'Bloc principal',items:selected.map((e,i)=>sessionItem(e,rxForExerciseV93(e,i),mixed))},{label:'Retour au calme',items:[{id:uid('cool'),name:'Respiration + mobilité ciblée',progressionGroup:'Retour au calme',group:'recovery',universe:'Récupération',cues:'Respire lentement et relâche les zones travaillées.',error:'Forcer dans une douleur.',fafaTip:'Redescends progressivement : respiration lente et mobilité confortable.',muscles:[],equipment:['tapis'],rx:{sets:1,reps:`${Math.max(3,Math.round(draft.duration*.08))} min`,rest:'—',simple:'Calme et sans douleur',coach:'RPE 2–3'}}]}];let title=`${draft.universe} · ${draft.subgoal}`,quality=qualityCheck(blocks),resource=resourcePlanV93(selected),intel=sessionIntelligenceV93(blocks[1].items);let s={id:uid('session'),clientId:draft.clientId||null,date:new Date().toISOString(),title,goal:draft.goal,subgoal:draft.subgoal,universe:draft.universe,method:draft.method,zone:draft.zone,level:mixed?'Mixte':draft.level,duration:draft.duration,frequency:draft.frequency,place:draft.place,equipment:[...draft.equipment],constraints:draft.constraints,mode:draft.mode,people:draft.mode==='group'?draft.people:null,stations:draft.mode==='group'?draft.stations:null,work:draft.work,transition:draft.transition,rounds:draft.rounds,equipmentQty:{...draft.equipmentQty},readiness:{energy:draft.energy,sleep:draft.sleep,stress:draft.stress,soreness:draft.soreness},blocks,why:whyChoiceV93(),quality,resourcePlan:resource,intelligence:intel,status:'planned',engineVersion:'V93'};state.sessions.unshift(s);let cc=state.clients.find(x=>x.id===draft.clientId);if(cc){cc.lastEnergy=draft.energy;cc.lastSleep=draft.sleep;cc.lastStress=draft.stress;cc.lastSoreness=draft.soreness}save();go(`session?id=${s.id}`)}
function whyChoiceV93(){let load=completedLoadV93(draft.clientId,4),fat=topEntriesV93(load.muscles,2).map(x=>x[0]).join(', ');return `FAFA équilibre les patterns, le volume musculaire, le lieu, le matériel et l’historique récent${fat?` ; vigilance actuelle : ${fat}`:''}.`}
function whyChoice(){return whyChoiceV93()}

function syncDraft(){draft.goal=$('#bGoal')?.value||draft.goal;draft.subgoal=$('#bSubgoal')?.value||draft.subgoal;draft.method=$('#bMethod')?.value||draft.method;draft.zone=$('#bZone')?.value||draft.zone;draft.place=$('#bPlace')?.value||draft.place;draft.frequency=parseNumV93($('#bFrequency')?.value,draft.frequency)||draft.frequency;draft.constraints=$('#bConstraints')?.value??draft.constraints;draft.people=parseNumV93($('#bPeople')?.value,draft.people)||draft.people;draft.stations=parseNumV93($('#bStations')?.value,draft.stations)||draft.stations;draft.rounds=parseNumV93($('#bRounds')?.value,draft.rounds)||draft.rounds;draft.work=parseNumV93($('#bWork')?.value,draft.work)||draft.work;draft.transition=parseNumV93($('#bTransition')?.value,draft.transition)||draft.transition;draft.energy=parseNumV93($('#bEnergy')?.value,draft.energy)||draft.energy;draft.sleep=parseNumV93($('#bSleep')?.value,draft.sleep)||draft.sleep;draft.stress=parseNumV93($('#bStress')?.value,draft.stress);draft.soreness=parseNumV93($('#bSoreness')?.value,draft.soreness);let inv=$('#bEquipmentQty')?.value;if(inv!==undefined){draft.equipmentQty={};String(inv).split(',').map(x=>x.trim()).filter(Boolean).forEach(x=>{let [k,v]=x.split(':');if(k&&Number(v)>0)draft.equipmentQty[k.trim()]=Number(v)})}}
function wizardBarV93(step){return `<div class="wizard-bar">${['Adhérent','Objectif','Contexte','Proposition FAFA'].map((x,i)=>`<button class="${step===i+1?'on':step>i+1?'done':''}" data-wizard-step="${i+1}"><i>${step>i+1?'✓':i+1}</i><span>${x}</span></button>`).join('')}</div>`}
function proposalSummaryV93(){let load=completedLoadV93(draft.clientId,4),fat=topEntriesV93(load.muscles,3),target=V93_GOAL_PATTERNS[goalTypeV93()]||V93_GOAL_PATTERNS.general;return `<div class="proposal-grid"><article><small>STRUCTURE CIBLE</small><b>${target.slice(0,5).join(' · ')}</b><p>Le moteur équilibrera la séance complète, pas seulement les exercices pris séparément.</p></article><article><small>RÉCUPÉRATION 4 JOURS</small><b>${load.sessions?`${load.sessions} séance(s) analysée(s)`:'Aucune charge récente'}</b><p>${fat.length?`Zones les plus chargées : ${fat.map(x=>`${x[0]} ${x[1].toFixed(1)}`).join(' · ')}`:'Pas de fatigue locale calculable pour le moment.'}</p></article><article><small>PRESCRIPTION</small><b>${safe(draft.method)} · ${draft.duration} min</b><p>RPE/RIR, repos, tempo et %1RM indicatif sont adaptés à l’objectif et à l’état du jour.</p></article></div>`}
function create(){draft.wizardStep=Math.min(4,Math.max(1,Number(draft.wizardStep)||1));let step=draft.wizardStep,family=familyForUniverse(draft.universe),methods=methodsFor(draft.universe),subs=subgoalsFor(draft.universe),c=state.clients.find(x=>x.id===draft.clientId);if(!subs.includes(draft.subgoal))draft.subgoal=subs[0];if(!methods.includes(draft.method))draft.method=methods[0];let body='';if(step===1)body=`<section class="wizard-panel"><p class="eyebrow">01 · POUR QUI ?</p><h2>Commence par le contexte humain.</h2><div class="mode-switch compact-switch">${[['individual','Individuel'],['group','Cours collectif'],['free','Création libre']].map(x=>`<button class="${draft.mode===x[0]?'on':''}" data-mode-v93="${x[0]}">${x[1]}</button>`).join('')}</div>${draft.mode==='individual'?`<label class="big-field">Adhérent<select id="bClientV93"><option value="">Sans adhérent</option>${state.clients.map(x=>`<option value="${x.id}" ${x.id===draft.clientId?'selected':''}>${safe(x.firstName)} ${safe(x.lastName||'')}</option>`).join('')}</select></label>${c?`<div class="profile-snapshot"><b>${safe(c.goal||'Objectif à préciser')}</b><span>${safe(c.level||'')} · ${safe(c.place||'')} · ${c.frequency||3}/sem.</span></div>`:''}`:`<div class="wizard-note"><b>${draft.mode==='group'?'Mode collectif intelligent':'Création libre'}</b><p>${draft.mode==='group'?'Le Resource Planner vérifiera les quantités simultanées de matériel et les rotations.':'Tu peux laisser FAFA proposer une structure ou démarrer immédiatement avec Mixer ma séance.'}</p>${draft.mode==='free'?'<button class="btn ghost" data-start-mixer>Démarrer vide</button>':''}</div>`}</section>`;if(step===2)body=`<section class="wizard-panel"><p class="eyebrow">02 · OBJECTIF</p><h2>Dis-moi ce que tu veux provoquer.</h2><label class="big-field">Objectif principal<input id="bGoal" value="${safe(draft.goal)}" placeholder="Ex. prise de muscle, 10 km, remise en forme…"></label><div class="field"><label>Univers principal</label><div class="family-pills">${MAIN_FAMILIES.map(f=>`<button class="${family.id===f.id?'on':''}" data-builder-family-v93="${f.id}">${safe(f.label)}</button>`).join('')}</div></div><div class="field"><label>Spécialité</label><div class="specialty-pills">${family.children.map(u=>`<button class="${draft.universe===u?'on':''}" data-universe-v93="${safe(u)}">${safe(u)} <small>${countUniverse(u)}</small></button>`).join('')}</div></div><label>Sous-objectif<select id="bSubgoal">${subs.map(x=>`<option ${draft.subgoal===x?'selected':''}>${safe(x)}</option>`).join('')}</select></label></section>`;if(step===3)body=`<section class="wizard-panel"><p class="eyebrow">03 · CONTEXTE</p><h2>Ce qui change réellement la prescription.</h2><div class="two"><label>Niveau<select id="bLevelV93">${LEVELS.map(l=>`<option ${draft.level===l?'selected':''}>${l}</option>`).join('')}</select></label><label>Lieu<select id="bPlace">${PLACES.map(x=>`<option ${draft.place===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="two"><label>Durée<select id="bDurationV93">${[20,30,45,60,75,90].map(n=>`<option value="${n}" ${draft.duration===n?'selected':''}>${n} min</option>`).join('')}</select></label><label>Matériel<button class="select-button" type="button" data-equipment>${draft.equipment.length?`${draft.equipment.length} sélectionné(s)`:'Choisir le matériel'}</button></label></div><details class="accordion" open><summary><span>État du jour</span><small>Énergie ${draft.energy}/10 · sommeil ${draft.sleep}/10</small></summary><section class="readiness-panel"><div class="readiness-grid"><label>Énergie <b>${draft.energy}/10</b><input id="bEnergy" type="range" min="1" max="10" value="${draft.energy}"></label><label>Sommeil <b>${draft.sleep}/10</b><input id="bSleep" type="range" min="1" max="10" value="${draft.sleep}"></label><label>Stress <b>${draft.stress}/10</b><input id="bStress" type="range" min="0" max="10" value="${draft.stress}"></label><label>Courbatures <b>${draft.soreness}/10</b><input id="bSoreness" type="range" min="0" max="10" value="${draft.soreness}"></label></div></section></details>${draft.mode==='group'?`<details class="accordion" open><summary><span>Organisation collective</span><small>${draft.people} participants · ${draft.stations} ateliers</small></summary>${groupBuilderV93()}</details>`:''}</section>`;if(step===4)body=`<section class="wizard-panel proposal-panel"><div class="proposal-head"><div><p class="eyebrow">04 · PROPOSITION FAFA</p><h2>FAFA a déjà préparé la logique de séance.</h2><p>Tu peux générer directement ou ouvrir les réglages experts.</p></div><button class="toggle ${draft.auto?'on':''}" data-toggle-auto-v93>${draft.auto?'AUTO':'MANUEL'}</button></div>${proposalSummaryV93()}<details class="accordion expert-settings" ${draft.auto?'':'open'}><summary><span>Réglages avancés Coach</span><small>Optionnels</small></summary><div class="two"><label>Méthode<select id="bMethod"><option>FAFA choisit</option>${methods.map(x=>`<option ${draft.method===x?'selected':''}>${safe(x)}</option>`).join('')}</select></label><label>Zone / qualité<select id="bZone">${ZONES.map(x=>`<option ${draft.zone===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="two"><label>Fréquence / semaine<input id="bFrequency" type="number" min="1" max="14" value="${draft.frequency}"></label><label>Contraintes / préférences<textarea id="bConstraints">${safe(draft.constraints)}</textarea></label></div></details><div class="why-box"><b>Pourquoi ce choix ?</b><p>${whyChoiceV93()}</p></div></section>`;return `${back()}<div class="page-head compact-head"><div><p class="eyebrow">CRÉATEUR INTELLIGENT</p><h1>Une décision à la fois.</h1><p>Adhérent → objectif → contexte → proposition FAFA. Les réglages experts restent disponibles sans encombrer le parcours.</p></div></div>${wizardBarV93(step)}<section class="wizard-shell">${body}<footer class="wizard-actions">${step>1?'<button class="btn ghost" data-wizard-prev>← Précédent</button>':'<span></span>'}${step<4?'<button class="btn primary" data-wizard-next>Continuer →</button>':'<button class="btn primary huge" data-build>Générer la séance intelligente</button>'}</footer></section>`}
function groupBuilderV93(){let total=Math.round((draft.work+draft.transition)*draft.stations*draft.rounds/60),inv=Object.entries(draft.equipmentQty||{}).map(([k,v])=>`${k}:${v}`).join(', ');return `<section class="group-panel"><div class="three"><label>Participants<input id="bPeople" type="number" min="2" value="${draft.people}"></label><label>Ateliers<input id="bStations" type="number" min="2" value="${draft.stations}"></label><label>Tours<input id="bRounds" type="number" min="1" value="${draft.rounds}"></label></div><div class="two"><label>Travail (s)<input id="bWork" type="number" value="${draft.work}"></label><label>Transition (s)<input id="bTransition" type="number" value="${draft.transition}"></label></div><label>Inventaire réel<input id="bEquipmentQty" value="${safe(inv)}" placeholder="kettlebell:4, rameur:2, tapis:8"><small>V93 additionne les besoins simultanés de TOUS les ateliers.</small></label><div class="rotation-preview"><b>${Math.ceil(draft.people/draft.stations)} personne(s) / atelier</b><span>${draft.stations} ateliers · ${draft.rounds} tours · ≈ ${total} min</span></div></section>`}
function groupBuilder(){return groupBuilderV93()}

function analyzeCompletedSessionV93(s){let intel=sessionIntelligenceV93(sessionMainItemsV93(s)),rpe=parseNumV93(s.completion?.rpe,7),tonnage=0;for(let it of sessionMainItemsV93(s)){let kg=parseNumV93(it.rx?.loadKg,0),sets=setsOfV93(it),reps=parseInt(String(it.rx?.reps||'').match(/\d+/)?.[0]||0,10);if(kg&&reps)tonnage+=kg*sets*reps}return {...intel,rpe,tonnage,loadScore:Math.round(Object.values(intel.muscles).reduce((a,b)=>a+b,0)*rpe*10)/10}}
function completeSession(){let s=state.sessions.find(x=>x.id===qp('id'));if(!s)return;s.status='completed';s.completedAt=new Date().toISOString();s.completion={rpe:Number($('#sessionRpe')?.value)||null,note:$('#sessionNote')?.value||''};s.trainingLoad=analyzeCompletedSessionV93(s);state.completionLogs.unshift({sessionId:s.id,clientId:s.clientId,rpe:s.completion.rpe,note:s.completion.note,date:s.completedAt,loadScore:s.trainingLoad.loadScore,tonnage:s.trainingLoad.tonnage});save();toast('Séance + charge d’entraînement enregistrées');render()}
function intelligenceCardV93(s){let intel=s.intelligence||sessionIntelligenceV93(sessionMainItemsV93(s)),recent=completedLoadV93(s.clientId,4),rp=s.resourcePlan;return `<section class="intelligence-card" id="v93Intelligence"><div class="intel-head"><div><p class="eyebrow">ANALYSE COACH</p><h2>Lecture globale de la séance</h2></div><span>ANALYSE ACTIVE</span></div><div class="intel-metrics"><article><small>Push / Pull</small><b>${intel.pushPull||`${intel.patterns?.push||0}:${intel.patterns?.pull||0}`}</b></article><article><small>Squat / Hinge</small><b>${intel.squatHinge||`${intel.patterns?.squat||0}:${intel.patterns?.hinge||0}`}</b></article><article><small>Charge récente</small><b>${recent.total.toFixed(1)}</b></article><article><small>Qualité</small><b>${s.quality?.ok?'OK':`${s.quality?.warnings?.length||0} alerte(s)`}</b></article></div>${intel.topMuscles?.length?`<div class="muscle-load-bars">${intel.topMuscles.map(([m,v])=>`<div><span>${safe(m)}</span><i><b style="width:${Math.min(100,v*5)}%"></b></i><strong>${Math.round(v)} séries</strong></div>`).join('')}</div>`:''}${rp?`<div class="resource-planner ${rp.conflicts?.length?'warn':''}"><div><b>Resource Planner</b><span>${rp.perStation} pers./atelier · besoins simultanés calculés</span></div>${Object.entries(rp.demand||{}).map(([eq,n])=>`<small>${safe(eq)} × ${n}</small>`).join('')}${rp.conflicts?.map(x=>`<p>⚠ ${safe(x)}</p>`).join('')||'<p>✓ Aucun conflit matériel simultané détecté.</p>'}</div>`:''}</section>`}
function clientLoadCardV93(c){let load=completedLoadV93(c.id,7),last=(state.sessions||[]).filter(s=>s.clientId===c.id&&s.status==='completed').slice(0,8),scores=last.map(s=>s.trainingLoad?.loadScore||analyzeCompletedSessionV93(s).loadScore),avg=scores.length?Math.round(scores.reduce((a,b)=>a+b,0)/scores.length):0;return `<section class="client-load-card" id="v93ClientLoad"><div><p class="eyebrow">CHARGE 7 JOURS</p><h2>Ce que le moteur voit avant de prescrire.</h2><p>${load.sessions} séance(s) terminée(s) · charge moyenne récente ${avg||'—'}</p></div><div class="load-tags">${topEntriesV93(load.muscles,5).map(([m,v])=>`<span>${safe(m)} <b>${v.toFixed(1)}</b></span>`).join('')||'<span>Aucune charge récente calculable</span>'}</div></section>`}
function enhanceRouteV93(){if(route()==='session'&&!$('#v93Intelligence')){let s=state.sessions.find(x=>x.id===qp('id')),anchor=$('.session-utility-bar')||$('.session-hero');if(s&&anchor)anchor.insertAdjacentHTML('afterend',intelligenceCardV93(s))}if(route()==='client'&&!$('#v93ClientLoad')){let c=state.clients.find(x=>x.id===qp('id')),anchor=$('.readiness-card');if(c&&anchor)anchor.insertAdjacentHTML('afterend',clientLoadCardV93(c))}}

function planGoalTypeV93(goal){let q=normalize(goal);if(q.includes('force'))return'force';if(q.includes('muscle')||q.includes('hypertroph'))return'hypertrophie';if(q.includes('course')||q.includes('cardio')||q.includes('endurance')||q.includes('trail')||q.includes('10 km')||q.includes('semi'))return'endurance';return'general'}
function planFocusesV93(goal,freq){let t=planGoalTypeV93(goal);if(t==='endurance'){let a=['Endurance fondamentale','Intervalles / qualité','Renforcement + technique','Sortie longue','Récupération active'];return Array.from({length:freq},(_,i)=>a[i%a.length])}if(freq>=4){let a=['Haut du corps A','Bas du corps A','Haut du corps B','Bas du corps B','Full Body technique'];return Array.from({length:freq},(_,i)=>a[i%a.length])}return Array.from({length:freq},(_,i)=>`Full Body ${String.fromCharCode(65+i)}`)}
function focusMatchV93(e,focus){let q=normalize(focus);if(q.includes('haut'))return e.group==='haut_du_corps'||e.group==='core';if(q.includes('bas'))return e.group==='bas_du_corps'||e.group==='core';if(q.includes('endurance')||q.includes('intervalles')||q.includes('sortie'))return ['Cardio','Cardio / Aérobic','Running / Trail'].includes(e.universe||e.family)||['cardio','power'].includes(patternOfV93(e));if(q.includes('renforcement + technique'))return ['core','squat','hinge','lunge'].includes(patternOfV93(e));return true}
function planExercisePoolV93(c,goal,level,focus){let eq=(c?.equipment||[]).map(normalize),gt=planGoalTypeV93(goal);let pool=EX.filter(e=>supportsLevel(e,level||'Débutant')&&focusMatchV93(e,focus));if(eq.length)pool=pool.filter(e=>{let req=externalEquipmentV93(e).map(normalize);return !req.length||req.every(q=>eq.includes(q))});let tokens=normalize(goal).split(/\s+/).filter(x=>x.length>4);return pool.map((e,i)=>{let txt=normalize((e.goals||[]).join(' ')+' '+(e.subgoals||[]).join(' ')+' '+e.universe+' '+e.name),s=100-i*.01;s+=tokens.filter(t=>txt.includes(t)).length*8;if(gt==='force'&&['squat','hinge','push','pull'].includes(patternOfV93(e)))s+=8;if(gt==='endurance'&&patternOfV93(e)==='cardio')s+=14;return{e,s}}).sort((a,b)=>b.s-a.s)}
function weekPrescriptionV93(week,total){let deload=total>=5&&week===Math.ceil(total*.75),phase=week/total;if(deload)return{week,label:'Allègement',volume:72,intensity:88,density:90,rir:4,instruction:'Réduis le volume et garde la technique. La fatigue doit redescendre.'};let volume=Math.min(118,100+(week-1)*4),intensity=Math.min(112,100+(week-1)*2),density=Math.min(110,100+(week-1)*1.5);return{week,label:week===1?'Base technique':phase<.55?'Construction':week===total?'Consolidation / test':'Progression',volume:Math.round(volume),intensity:Math.round(intensity),density:Math.round(density),rir:week===1?3:week===total?2:Math.max(2,3-Math.floor((week-1)/3)),instruction:week===1?'Fixe les repères et garde de la marge.':week===total?'Consolide ou teste un repère sans sacrifier la technique.':'Progresse sur volume, charge ou densité selon la récupération.'}}
function planRxV93(e,goal,w){let t=planGoalTypeV93(goal),sets=t==='force'?4:t==='endurance'?3:3,reps=t==='force'?'4–6':t==='hypertrophie'?'8–12':t==='endurance'?(patternOfV93(e)==='cardio'?'3–8 min':'12–20'):'8–15',rest=t==='force'?'2–4 min':t==='endurance'?'30–75 s':'75–120 s';sets=Math.max(2,Math.round(sets*w.volume/100));let pct=t==='force'?Math.round(78*w.intensity/100):t==='hypertrophie'?Math.round(68*w.intensity/100):null;return{sets,reps,rest,rir:w.rir,percent:pct,coach:`S${w.week} · ${w.label} · RIR ${w.rir}`,simple:`Progression ${w.volume}% volume`}}
function balancedSelectPlanV93(pool,n,used={}){let rem=pool.slice(0,140),sel=[];while(sel.length<n&&rem.length){let best=-1,bestScore=-1e9;for(let i=0;i<rem.length;i++){let e=rem[i].e,s=(rem[i].s??100)-(used[e.id]||0)*24;let p=patternOfV93(e),counts={};for(let x of sel)counts[patternOfV93(x)]=(counts[patternOfV93(x)]||0)+1;if(p==='pull'&&(counts.push||0)>(counts.pull||0))s+=12;if((p==='squat'||p==='hinge')&&!sel.some(x=>patternOfV93(x)===p))s+=10;let same=sel.filter(x=>(x.muscles||[]).some(m=>(e.muscles||[]).includes(m))).length;s-=same*4;if(s>bestScore){bestScore=s;best=i}}sel.push(rem.splice(best,1)[0].e)}return sel}
function buildPlanWeeksV93(c,f,n){let focuses=planFocusesV93(f.goal,Math.max(1,Math.min(7,Number(f.frequency)||3))),used={},baseDays=focuses.map((focus,di)=>{let pool=planExercisePoolV93(c,f.goal,f.level,focus),sel=balancedSelectPlanV93(pool,focus.includes('Endurance')||focus.includes('Intervalles')?5:6,used);sel.forEach(e=>used[e.id]=(used[e.id]||0)+1);return{day:di+1,focus,title:`J${di+1} · ${focus}`,exerciseIds:sel.map(e=>e.id)}});return Array.from({length:n},(_,i)=>{let w=weekPrescriptionV93(i+1,n);return{...w,days:baseDays.map(d=>({...d,exercises:d.exerciseIds.map(id=>{let e=EX.find(x=>x.id===id);return{id,name:e?.name||id,group:e?.group||'',muscles:e?.muscles||[],equipment:e?.equipment||[],rx:planRxV93(e||{},f.goal,w)}})}))}})}
function createPlanFromForm(form){let f=Object.fromEntries(new FormData(form)),n=Number(f.weeks)||6,c=state.clients.find(x=>x.id===f.clientId),p={id:uid('plan'),clientId:f.clientId||null,title:f.title||'Plan FAFATRAINING',goal:f.goal||'Progression',level:f.level||'Débutant',duration:Number(f.duration)||45,frequency:Number(f.frequency)||3,currentWeek:1,createdAt:new Date().toISOString(),engineVersion:'V93',weeks:buildPlanWeeksV93(c,f,n)};state.plans.unshift(p);save();go(`plan?id=${p.id}`)}
