function planPage(){let id=qp('id');if(id){let p=(state.plans||[]).find(x=>x.id===id);if(!p)return'<div class="empty">Plan introuvable.</div>';let w=p.weeks.find(x=>x.week===(p.currentWeek||1))||p.weeks[0];return `${back()}<section class="plan-head"><div><p class="eyebrow">PLAN INTELLIGENT</p><h1>${safe(p.title)}</h1><p>${safe(p.goal)} · ${safe(p.level)} · ${p.frequency}/sem. · ${p.duration} min</p></div><div class="actions"><button class="btn ghost" data-duplicate-plan="${p.id}">Dupliquer</button><button class="btn primary" data-print-plan>Imprimer</button></div></section><section class="week-grid compact-weeks">${p.weeks.map(x=>`<article class="week-card ${x.week===(p.currentWeek||1)?'current':''}"><span>S${x.week}</span><h3>${safe(x.label)}</h3><b>Vol. ${x.volume}% · Int. ${x.intensity||100}%</b><p>RIR cible ${x.rir??'—'} · densité ${x.density||100}%</p><button data-set-week="${x.week}" data-plan="${p.id}">${x.week===(p.currentWeek||1)?'Semaine actuelle':'Afficher'}</button></article>`).join('')}</section><section class="current-week-detail"><div class="week-detail-head"><div><p class="eyebrow">SEMAINE ${w.week}</p><h2>${safe(w.label)}</h2><p>${safe(w.instruction)}</p></div><div class="week-kpis"><span>Volume <b>${w.volume}%</b></span><span>Intensité <b>${w.intensity||100}%</b></span><span>Densité <b>${w.density||100}%</b></span><span>RIR <b>${w.rir??'—'}</b></span></div></div><div class="plan-days">${(w.days||[]).map((d,di)=>`<article class="plan-day"><header><div><small>JOUR ${d.day}</small><h3>${safe(d.focus)}</h3></div><button class="btn primary" data-plan-session="${p.id}:${w.week}:${di}">Créer la séance</button></header><div class="plan-exercises">${d.exercises.map(e=>`<div><b>${safe(e.name)}</b><span>${e.rx.sets} × ${safe(e.rx.reps)} · repos ${safe(e.rx.rest)}${e.rx.percent?` · ${e.rx.percent}%1RM`:''} · RIR ${e.rx.rir}</span></div>`).join('')}</div></article>`).join('')}</div></section>`}let clients=state.clients||[],c=clients.find(x=>x.id===qp('client'))||clients[0];return `${back()}<div class="page-head"><div><p class="eyebrow">NOUVEAU PLAN</p><h1>Construire une vraie programmation.</h1><p>Les semaines contiendront des jours et des séances prescrites, pas seulement une consigne générale.</p></div></div><form id="planForm" class="profile-form"><label>Adhérent<select name="clientId"><option value="">Sans adhérent</option>${clients.map(x=>`<option value="${x.id}" ${c?.id===x.id?'selected':''}>${safe(x.firstName)} ${safe(x.lastName||'')}</option>`).join('')}</select></label><div class="two"><label>Nom du plan<input name="title" value="${safe(c?`Plan ${c.firstName} · ${c.goal||'Progression'}`:'Plan FAFATRAINING')}"></label><label>Objectif<input name="goal" value="${safe(c?.goal||'Remise en forme')}"></label></div><div class="four"><label>Niveau<select name="level">${LEVELS.map(l=>`<option ${c?.level===l?'selected':''}>${l}</option>`).join('')}</select></label><label>Durée séance<input name="duration" type="number" value="${c?.duration||state.coach.defaultDuration||45}"></label><label>Fréquence<input name="frequency" type="number" min="1" max="7" value="${c?.frequency||3}"></label><label>Semaines<select name="weeks"><option>4</option><option selected>6</option><option>8</option></select></label></div><button class="btn primary">Créer le plan intelligent</button></form>`}
function createPlanSessionV93(planId,weekNo,dayIndex){let p=state.plans.find(x=>x.id===planId),w=p?.weeks.find(x=>x.week===Number(weekNo)),d=w?.days?.[Number(dayIndex)];if(!p||!w||!d)return;let items=d.exercises.map(x=>{let e=EX.find(z=>z.id===x.id);return e?sessionItem(e,x.rx,p.level==='Mixte'):{...x,progressionGroup:x.name,rx:x.rx}}),blocks=[{label:'Échauffement',items:[]},{label:'Bloc principal',items},{label:'Retour au calme',items:[]}],s={id:uid('session'),clientId:p.clientId||null,date:new Date().toISOString(),title:`${p.title} · S${w.week} J${d.day}`,goal:p.goal,subgoal:d.focus,universe:'Planification V93',method:'Plan programmé',zone:'Corps entier',level:p.level,duration:p.duration,frequency:p.frequency,place:state.clients.find(c=>c.id===p.clientId)?.place||'À préciser',equipment:[],constraints:'',mode:'individual',blocks,status:'planned',engineVersion:'V93 Plan',planRef:{planId:p.id,week:w.week,day:d.day},intelligence:sessionIntelligenceV93(items),quality:{ok:true,warnings:[],duration:p.duration,checkedAt:new Date().toISOString()}};state.sessions.unshift(s);save();go(`session?id=${s.id}`)}

let STUDIO_THEME_V93='premium';
