function socialVisualPathV93(s){return `assets/visuals/${universeVisual(s.universe||'')}`}
function drawVisualV93(ctx,s,W,H,alpha=.42){let path=socialVisualPathV93(s),img=SOCIAL_IMG_CACHE_V93[path];if(!img){img=new Image();SOCIAL_IMG_CACHE_V93[path]=img;img.onload=()=>{if(route()==='studio')drawStudioPage(s,1,state.ui?.studioFormat||'post')};img.src=path;return}if(!img.complete||!img.naturalWidth)return;ctx.save();ctx.globalAlpha=alpha;let scale=Math.max(W*.58/img.naturalWidth,H/img.naturalHeight),dw=img.naturalWidth*scale,dh=img.naturalHeight*scale;ctx.drawImage(img,W-dw,0,dw,dh);ctx.restore()}
