const BODY_REGIONS_V94=[['Tous','Tous'],['Corps entier','Corps entier'],['Haut du corps','Haut'],['Bas du corps','Bas'],['Core / abdos','Core'],['Cardio / locomotion','Cardio'],['Athlétique','Athlétique'],['Mobilité','Mobilité'],['Boxe / combat','Boxe']];
function bodyRegionsForV94(e){let out=new Set(),g=normalize(e.group||''),u=normalize(e.universe||e.family||''),m=normalize((e.muscles||[]).join(' ')),p=normalize(e.pattern||'');if(g.includes('full')||g==='full_body')out.add('Corps entier');if(g.includes('haut')||/(pector|dos|epaule|biceps|triceps|dorsal|bras)/.test(m))out.add('Haut du corps');if(g.includes('bas')||/(fess|quad|ischio|mollet|hanche|adduct|jambes)/.test(m))out.add('Bas du corps');if(g.includes('core')||/(abdo|core|oblique|gainage)/.test(m))out.add('Core / abdos');if(g.includes('cardio')||u.includes('cardio')||u.includes('running')||u.includes('endurance')||m.includes('cardio')||/run|sprint|rameur|ski|bike/.test(normalize(e.name)))out.add('Cardio / locomotion');if(u.includes('preparation physique')||/puissance|explos|plyo|agilit|coordination/.test(u+' '+p+' '+normalize((e.goals||[]).join(' '))))out.add('Athlétique');if(u.includes('mobilite')||u.includes('souplesse')||u.includes('recuperation')||u.includes('prevention')||/mobil|stretch|etirement/.test(normalize(e.name)))out.add('Mobilité');if(u.includes('boxe')||g.includes('boxe')||/jab|cross|crochet|uppercut|shadow|slip/.test(normalize(e.name)))out.add('Boxe / combat');let functionalCount=['Haut du corps','Bas du corps','Core / abdos'].filter(x=>out.has(x)).length;if(functionalCount>=2||['cardio','power','carry'].includes(patternOfV93(e)))out.add('Corps entier');if(!out.size)out.add('Corps entier');return [...out]}
function bodyRegionFor(e){let r=bodyRegionsForV94(e);if(r.includes('Boxe / combat'))return 'Boxe / combat';if(r.includes('Mobilité'))return 'Mobilité';if((e.group||'')==='full_body'||r.includes('Corps entier'))return 'Corps entier';return r[0]||'Corps entier'}
function musclesForCurrentRegion(){let list=EX.filter(e=>filter.region==='Tous'||bodyRegionsForV94(e).includes(filter.region)).flatMap(e=>e.muscles||[]).filter(Boolean),counts={};list.forEach(m=>counts[m]=(counts[m]||0)+1);return Object.entries(counts).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'fr')).slice(0,40).map(x=>x[0])}
function filteredExercises(){return EX.filter(e=>(filter.family==='Tous'||(e.uiFamily||familyForUniverse(e.universe||e.family).label)===filter.family)&&(filter.region==='Tous'||bodyRegionsForV94(e).includes(filter.region))&&(filter.muscle==='Tous'||(e.muscles||[]).includes(filter.muscle))&&(filter.universe==='Tous'||(e.universe||e.family)===filter.universe)&&(filter.group==='Tous'||e.group===filter.group)&&supportsLevel(e,filter.level)&&(!filter.q||normalize((e.search||'')+' '+e.name+' '+(e.muscles||[]).join(' ')).includes(normalize(filter.q)))&&(!filter.equipment.length||filter.equipment.every(q=>(e.equipment||[]).includes(q)))&&(!filter.favorites||state.favorites.includes(e.id)))}
function movementPrescriptionV93(e){let goals=normalize((e.goals||e.subgoals||[]).join(' ')+' '+(e.universe||'')),cards=[];if(/force|puissance|explos/.test(goals)||/squat|hinge|push|pull/.test(normalize(e.pattern||'')))cards.push(['FORCE / PUISSANCE','3 à 5 séries · 3 à 6 répétitions','2 à 3 min','Garde encore 2 à 3 répétitions possibles avant l’échec (RIR 2–3).']);if(/hypertroph|renfo|musculation/.test(goals)||['haut_du_corps','bas_du_corps'].includes(e.group))cards.push(['RENFORCEMENT','3 à 4 séries · 8 à 12 répétitions','60 à 120 s','Arrête la série avec 1 à 3 répétitions encore possibles (RIR 1–3).']);cards.push(['ENDURANCE / CONDITIONING',e.mode==='time'?'3 à 5 séries · 30 à 60 secondes':'2 à 4 séries · 12 à 20 répétitions','30 à 60 s','Effort modéré à soutenu, environ 6 à 8/10 (RPE 6–8).']);return cards.slice(0,3)}
function coachGlossaryV94(){return `<details class="coach-glossary"><summary>Comprendre les repères de prescription <span>?</span></summary><div><p><b>Séries × répétitions</b> : « 4 séries · 8 répétitions » signifie faire 8 répétitions, récupérer, puis recommencer jusqu’à 4 séries.</p><p><b>RIR</b> (« répétitions en réserve ») : RIR 2 = tu arrêtes alors que tu pourrais encore faire environ 2 répétitions propres.</p><p><b>RPE</b> (« effort perçu ») : échelle de 1 à 10. RPE 6 = modéré ; RPE 8 = difficile mais maîtrisé ; RPE 10 = effort maximal.</p><p><b>Tempo 3-1-1</b> : 3 s pour descendre, 1 s de pause, 1 s pour remonter. Quand aucun tempo n’est indiqué, garde un mouvement contrôlé.</p></div></details>`}
function library(){filter.family=filter.family||'Tous';filter.region=filter.region||'Tous';filter.muscle=filter.muscle||'Tous';filter.favorites=!!filter.favorites;libraryLimit=libraryLimit||60;let list=filteredExercises(),visible=list.slice(0,libraryLimit),muscles=musclesForCurrentRegion(),activeFilters=(filter.family!=='Tous')+(filter.region!=='Tous')+(filter.muscle!=='Tous')+(filter.universe!=='Tous')+(filter.group!=='Tous')+(filter.level!=='Tous')+filter.equipment.length+(filter.favorites?1:0);return `${back()}<div class="page-head compact-head library-head"><div><p class="eyebrow">BIBLIOTHÈQUE MOUVEMENTS</p><h1>${EX.length} mouvements techniques</h1><p>Commence par une zone, affine par muscle puis par matériel. Un mouvement peut apparaître dans plusieurs zones quand c’est pertinent.</p><span class="result-count"><b id="libraryCount" aria-live="polite">${list.length}</b> résultat${list.length>1?'s':''}</span></div><button class="btn ghost" data-library-favorites>${filter.favorites?'★ Favoris actifs':'☆ Favoris'}</button></div><section class="body-region-tabs">${BODY_REGIONS_V94.map(([value,label])=>`<button class="${filter.region===value?'on':''}" data-body-region="${safe(value)}">${safe(label)}</button>`).join('')}</section><section class="library-bar v94-library-bar"><div class="search-field"><span>⌕</span><input id="libQ" value="${safe(filter.q)}" placeholder="Ex. pectoraux, rowing, élastique…" autocomplete="off"></div><label class="compact-select"><small>MUSCLE</small><select id="libMuscleV93"><option value="Tous">Tous les muscles</option>${muscles.map(m=>`<option ${filter.muscle===m?'selected':''}>${safe(m)}</option>`).join('')}</select></label><label class="compact-select"><small>UNIVERS</small><select id="libFamilyV91"><option>Tous</option>${MAIN_FAMILIES.map(f=>`<option ${filter.family===f.label?'selected':''}>${safe(f.label)}</option>`).join('')}</select></label><button class="filter-button ${activeFilters?'on':''}" data-open-library-filters>Filtres${activeFilters?` · ${activeFilters}`:''}</button><button class="ghost-mini" data-lib-reset-v91>Effacer</button></section><section id="libraryResults" class="movement-grid compact-movement-grid">${visible.map(movementCard).join('')||`<div class="empty"><h2>Aucun mouvement</h2><p>Efface un filtre ou élargis ta recherche.</p></div>`}</section><div id="libraryMoreWrap">${visible.length<list.length?`<div class="load-more"><span>${visible.length} / ${list.length}</span><button class="btn ghost" data-library-more>Afficher ${Math.min(60,list.length-visible.length)} de plus</button></div>`:''}</div>`}
function movementCard(e){let fav=state.favorites.includes(e.id),primary=(e.muscles||[])[0]||e.group||'',secondary=(e.muscles||[]).slice(1,3).join(' · '),regions=bodyRegionsForV94(e).slice(0,2).join(' · ');return `<button class="movement-card compact-movement" data-ex-info="${e.id}"><div class="movement-top"><span>${safe(regions)}</span><b>${fav?'★ FAVORI':'FICHE TECHNIQUE'}</b></div><div class="movement-body"><h3>${safe(e.name)}</h3><p>${safe(e.cues||e.fafaTip||'')}</p></div><div class="movement-meta"><span><b>${safe(primary)}</b>${secondary?` · ${safe(secondary)}`:''}</span><small>${safe((e.equipment||[]).slice(0,2).join(' · ')||'Sans matériel')}</small></div><span class="open-arrow">Exécution · variantes · prescription →</span></button>`}
function updateLibraryResults(){let list=filteredExercises(),visible=list.slice(0,libraryLimit),count=$('#libraryCount'),grid=$('#libraryResults'),more=$('#libraryMoreWrap');if(count)count.textContent=list.length;if(grid)grid.innerHTML=visible.map(movementCard).join('')||'<div class="empty"><h2>Aucun mouvement</h2><p>Efface un filtre ou élargis ta recherche.</p></div>';if(more)more.innerHTML=visible.length<list.length?`<div class="load-more"><span>${visible.length} / ${list.length}</span><button class="btn ghost" data-library-more>Afficher ${Math.min(60,list.length-visible.length)} de plus</button></div>`:'';bindDynamicLibrary()}
const PROGRAM_TYPE_ORDER_V94={
'Musculation & Renforcement':['Poids du corps','Force & hypertrophie','Bas du corps','Core','Petit matériel'],
'Cardio & Endurance':['Running','Trail','Endurance','Intervalles / HIIT','Maison / nomade','Machines'],
'Cross & Functional':['WOD / Cross Training','HIIT / MetCon','Functional','Bootcamp'],
'HYROX':['Complet / hybride','Running','Stations','Force / Carry'],
'Boxe & Combat':['Technique','Shadow','Sac / Pattes','Conditionnement'],
'Préparation Physique':['Vitesse / Agilité','Puissance / Plyométrie','Sport spécifique','Tests'],
'Mobilité & Prévention':['Mobilité globale','Hanches / Bas','Épaules / Haut','Récupération'],
'Cours Collectifs':['Ateliers / Circuit','Team / WOD','Cardio / Outdoor','Renforcement']};
function programTypeV94(t){let s=normalize([t.title,t.category,t.focus,t.format,...(t.tags||[])].join(' ')),f=t.family;
 if(f==='Musculation & Renforcement'){if(/fessier|lower|bas du corps/.test(s))return'Bas du corps';if(/core|abdo|gainage/.test(s))return'Core';if(/elastique|haltere|kettlebell|fonctionnelle/.test(s))return'Petit matériel';if(/sans materiel|poids du corps|bodyweight/.test(s))return'Poids du corps';return'Force & hypertrophie'}
 if(f==='Cardio & Endurance'){if(/trail|cote|montee|descente/.test(s))return'Trail';if(/running|5 km|10 km|marche-course/.test(s))return'Running';if(/hiit|20\/10|intervalle|fartlek|tempo/.test(s))return'Intervalles / HIIT';if(/rameur|ski|bike|machine/.test(s))return'Machines';if(/maison|corde|sans impact|sans materiel/.test(s))return'Maison / nomade';return'Endurance'}
 if(f==='Cross & Functional'){if(/bootcamp/.test(s))return'Bootcamp';if(/functional|carry/.test(s))return'Functional';if(/hiit|metabolique|metcon/.test(s))return'HIIT / MetCon';return'WOD / Cross Training'}
 if(f==='HYROX'){if(/running|run focus/.test(s))return'Running';if(/grip|carry|dumbbell|force/.test(s))return'Force / Carry';if(/wall ball|sled|machine|transition|station/.test(s))return'Stations';return'Complet / hybride'}
 if(f==='Boxe & Combat'){if(/shadow/.test(s))return'Shadow';if(/sac|pattes/.test(s))return'Sac / Pattes';if(/cardio|conditioning|endurance|renforcement/.test(s))return'Conditionnement';return'Technique'}
 if(f==='Préparation Physique'){if(/test|challenge/.test(s))return'Tests';if(/foot|boxe|runner/.test(s))return'Sport spécifique';if(/puissance|plyo|explos/.test(s))return'Puissance / Plyométrie';return'Vitesse / Agilité'}
 if(f==='Mobilité & Prévention'){if(/hanche|cheville|runner/.test(s))return'Hanches / Bas';if(/epaule|thorax/.test(s))return'Épaules / Haut';if(/recuper|post-seance|respiration|bureau/.test(s))return'Récupération';return'Mobilité globale'}
 if(f==='Cours Collectifs'){if(/outdoor|cardio|course/.test(s))return'Cardio / Outdoor';if(/team|wod|relais|duo|solidarite|cohesion/.test(s))return'Team / WOD';if(/force|halter|renfo/.test(s))return'Renforcement';return'Ateliers / Circuit'}
 return t.category||'Autre'}
function programTypesForFamilyV94(family){if(!family||family==='Tous')return[];let preferred=PROGRAM_TYPE_ORDER_V94[family]||[],present=new Set(TEMPLATES.filter(t=>t.family===family).map(programTypeV94));return preferred.filter(x=>present.has(x)).concat([...present].filter(x=>!preferred.includes(x)).sort())}
function friendlyIntensityV94(v){let s=String(v||'').trim();let m=s.match(/RPE\s*([0-9]+(?:\s*[–-]\s*[0-9]+)?)/i);if(m)return`Effort ${m[1].replace('-','–')}/10`;let r=s.match(/RIR\s*([0-9]+(?:\s*[–-]\s*[0-9]+)?)/i);if(r)return`${r[1].replace('-','–')} répétition(s) en réserve`;return s}
function programEquipmentClassV94(t){if(t.equipmentClass)return t.equipmentClass;let eq=(t.equipment||[]).map(normalize),portable=['poids du corps','tapis','elastique','halteres','haltere','kettlebell','corde','corde a sauter','mini band','medecine ball','medicine ball','cones','exterieur','parc','terrain'];if(!eq.length||eq.every(x=>['poids du corps','exterieur','terrain','parc'].includes(x)))return 'Sans matériel';if(eq.every(x=>portable.includes(x)))return 'Petit matériel';return 'Salle / spécifique'}
function filteredPrograms(){programFilter.equipment=programFilter.equipment||'Tous';programFilter.type=programFilter.type||'Tous';let q=programFilter.q||'',family=programFilter.family||'Tous',eq=programFilter.equipment,type=programFilter.type;return TEMPLATES.filter(t=>(family==='Tous'||t.family===family)&&(eq==='Tous'||programEquipmentClassV94(t)===eq)&&(type==='Tous'||programTypeV94(t)===type)&&(!q||normalize(t.title+' '+t.category+' '+t.focus+' '+t.format+' '+t.family+' '+programTypeV94(t)+' '+(t.tags||[]).join(' ')+' '+(t.equipment||[]).join(' ')).includes(normalize(q))))}
function programRow(t){let freq=programFrequencyV93(t),eq=programEquipmentClassV94(t);return `<button class="program-card" data-preview-template="${t.id}"><div class="program-card-top"><span>${safe(t.category||t.family)}</span><b>${t.duration} MIN</b></div><h3>${safe(t.title)}</h3><p>${safe(t.focus)}</p><div class="program-card-meta"><span>${safe(t.format)}</span><span>${freq}×/sem.</span><span>${safe(eq)}</span></div><footer><small>${safe((t.equipment||[]).slice(0,3).join(' · ')||'Poids du corps')}</small><b>Ouvrir →</b></footer></button>`}
function templates(){programFilter.equipment=programFilter.equipment||'Tous';programFilter.type=programFilter.type||'Tous';let list=filteredPrograms(),types=programTypesForFamilyV94(programFilter.family);return `${back()}<div class="page-head compact-head"><div><p class="eyebrow">PROGRAMMOTHÈQUE FAFATRAINING</p><h1>${TEMPLATES.length} programmes prêts à coacher</h1><p>8 univers équilibrés. Choisis le terrain, le format puis le matériel. Chaque programme reste entièrement adaptable à l’adhérent.</p><span class="result-count"><b id="programCount" aria-live="polite">${list.length}</b> résultat${list.length>1?'s':''}</span></div><div class="actions"><button class="btn ghost" data-go="blocks">Mes blocs</button></div></div><section class="program-family-tabs"><button class="${programFilter.family==='Tous'?'on':''}" data-program-family-v93="Tous">Tous</button>${MAIN_FAMILIES.map(f=>`<button class="${programFilter.family===f.label?'on':''}" data-program-family-v93="${safe(f.label)}">${safe(f.label)} · ${TEMPLATES.filter(t=>t.family===f.label).length}</button>`).join('')}</section>${types.length?`<section class="program-type-tabs"><span>TYPE</span><button class="${programFilter.type==='Tous'?'on':''}" data-program-type-v94="Tous">Tous</button>${types.map(x=>`<button class="${programFilter.type===x?'on':''}" data-program-type-v94="${safe(x)}">${safe(x)} · ${TEMPLATES.filter(t=>t.family===programFilter.family&&programTypeV94(t)===x).length}</button>`).join('')}</section>`:''}<section class="program-equipment-tabs"><span>MATÉRIEL</span>${['Tous','Sans matériel','Nomade / petit matériel','Salle / spécifique'].map(x=>{let raw=x==='Nomade / petit matériel'?'Petit matériel':x;return`<button class="${programFilter.equipment===raw?'on':''}" data-program-equipment-v94="${safe(raw)}">${safe(x)}</button>`}).join('')}</section><section class="program-toolbar v93-program-toolbar"><div class="search-field"><span>⌕</span><input id="programQ" value="${safe(programFilter.q||'')}" placeholder="Ex. CrossFit, WOD, HYROX, maison, haltères, trail…" autocomplete="off"></div><button class="ghost-mini" data-program-reset>Effacer</button></section>${state.savedTemplates.length?`<section class="saved-models"><div class="results-head"><h2>Mes modèles · ${state.savedTemplates.length}</h2></div><div class="program-list">${state.savedTemplates.map(s=>`<button class="program-row saved-row" data-use-saved="${s.id}"><span class="program-icon">M</span><div><small>MODÈLE PERSONNEL</small><h3>${safe(s.title)}</h3><p>${s.session?.duration||'—'} min · adaptable</p></div><b>Utiliser →</b></button>`).join('')}</div></section>`:''}<section id="programList" class="program-sections">${programSectionsHtmlV93(list)}</section>`}
function sessionsThisMonthV94(){let d=new Date(),m=d.getMonth(),y=d.getFullYear();return (state.sessions||[]).filter(s=>{let x=new Date(s.completedAt||s.date);return s.status==='completed'&&x.getMonth()===m&&x.getFullYear()===y}).length}
function clientsToPlanV94(){return (state.clients||[]).filter(c=>!(state.sessions||[]).some(s=>s.clientId===c.id&&s.status!=='completed')).length}
function home(){let next=(state.sessions||[]).find(s=>s.status!=='completed')||state.sessions[0],lastClient=(next?.clientId&&state.clients.find(c=>c.id===next.clientId))||state.clients[state.clients.length-1],plan=(state.plans||[])[0];const workspace=[{label:'COACHING',items:[['◎','Adhérents','Profils & suivi','data-go="clients"'],['＋','Créer','Séance guidée','data-go="create"'],['✦','Mixer','Création libre','data-start-mixer'],['↺','Historique','Séances terminées','data-go="history"']]},{label:'CONTENU',items:[['▦','Mouvements','Technique & variantes','data-go="library"'],['◧','Programmes',`${TEMPLATES.length} programmes`,'data-go="templates"'],['◫','Plans','Cycles 4–8 semaines','data-go="plans"'],['▤','Blocs','Modèles réutilisables','data-go="blocks"']]},{label:'OUTILS',items:[['⏱','Timer','Chrono & intervalles','data-open-timer'],['⌕','Recherche','Tout retrouver','data-go="search"'],['⇧','Studio','Social & PDF','data-go="studio"'],['◉','Collectif','Ateliers & rotations','data-mode-start="group"']]}];return `<section class="coach-dashboard v94-home"><div class="dashboard-brand"><div><p class="eyebrow">QG DU COACH</p><h1>Pilote ta journée. <em>Garde le contrôle.</em></h1><p>Seulement les informations qui demandent ton attention. Les outils restent dans ton poste de commande.</p><div class="home-status"><span><b>${state.clients.length}</b> adhérent${state.clients.length>1?'s':''}</span><span><b>${sessionsThisMonthV94()}</b> séance${sessionsThisMonthV94()>1?'s':''} ce mois</span><span class="${clientsToPlanV94()?'attention':''}"><b>${clientsToPlanV94()}</b> à programmer</span></div></div><img class="dashboard-avatar" src="assets/visuals/avatar-coach.jpeg" alt="Coach FAFATRAINING" decoding="async"></div><div class="dashboard-live"><article><small>DERNIER ADHÉRENT</small>${lastClient?`<b>${safe(lastClient.firstName)} ${safe(lastClient.lastName||'')}</b><span>${safe(lastClient.goal||'Profil enregistré')}</span><button data-open-client="${lastClient.id}">Voir →</button>`:`<b>Aucun adhérent</b><span>Ta base client est vide.</span><button data-go="clientEdit">Ajouter →</button>`}</article><article><small>PROCHAINE SÉANCE</small>${next?`<b>${safe(next.title)}</b><span>${next.duration} min · ${safe(next.goal||next.level||'')}</span><button data-open-session="${next.id}">Ouvrir →</button>`:`<b>Rien de programmé</b><span>Prépare la prochaine séance depuis Créer.</span><button data-go="create">Préparer →</button>`}</article><article><small>CYCLE EN COURS</small>${plan?`<b>${safe(plan.title)}</b><span>S${plan.currentWeek||1}/${plan.weeks.length}</span><button data-open-plan="${plan.id}">Continuer →</button>`:`<b>Aucun cycle actif</b><span>Utile seulement pour une progression sur plusieurs semaines.</span><button data-go="plans">Voir les plans →</button>`}</article></div></section><div class="section-title compact-title"><div><p class="eyebrow">ARSENAL COACH</p><h2>Tout ce qu’il te faut. Rien de trop.</h2><p>Une seule porte d’entrée par fonction. Rapide, clair, sans doublon.</p></div></div><section class="workspace-groups">${workspace.map(g=>`<article class="workspace-group"><header>${g.label}</header><div>${g.items.map(i=>`<button class="workspace-pill" ${i[3]}><i>${i[0]}</i><span><b>${i[1]}</b><small>${i[2]}</small></span><strong>›</strong></button>`).join('')}</div></article>`).join('')}</section><div class="section-title compact-title universe-title"><div><p class="eyebrow">TERRAINS DE PERFORMANCE</p><h2>8 univers. Une signature FAFATRAINING.</h2><p>Choisis ton terrain. FAFA adapte ensuite la prescription au profil, au contexte et au matériel.</p></div></div><section class="family-grid">${MAIN_FAMILIES.map((f,i)=>`<button class="family-card family-${i+1} tilt" data-open-family="${f.id}" style="--card-bg:url('${f.visual}')"><img src="${f.visual}" alt="${safe(f.label)}" loading="lazy" decoding="async"><span class="family-shade"></span><div class="family-card-copy"><small>${TEMPLATES.filter(t=>t.family===f.label).length} PROGRAMMES · BIBLIOTHÈQUE LIÉE</small><h3>${safe(f.label)}</h3><p>${f.children.slice(0,3).map(safe).join(' · ')}${f.children.length>3?'…':''}</p><b>Explorer →</b></div></button>`).join('')}</section>`}
function shell(body){let rm=state.ui?.readingMode||'coach',r=route(),active={home:'home',clients:'clients',client:'clients',clientEdit:'clients',create:'create',plans:'plans',plan:'plans',library:'library',templates:'home',blocks:'home',session:'create',studio:'home',search:'home',coach:'home',history:'home'}[r]||'home';let utilities=r==='home'?`<button class="reading-chip" data-reading-mode>${rm==='coach'?'MODE COACH':'MODE SIMPLE'}</button><button class="coach-chip" data-go="coach">⚙ Coach</button>`:`<button class="top-timer" data-open-timer>⏱ Timer</button><button class="top-search" data-go="search">⌕ Recherche</button><button class="reading-chip" data-reading-mode>${rm==='coach'?'MODE COACH':'MODE SIMPLE'}</button><button class="coach-chip" data-go="coach">⚙ Coach</button>`;return `<div class="ambient a1"></div><div class="ambient a2"></div><main class="shell app-enter reading-${rm}"><header class="topbar"><button class="brand" data-go="home"><span class="brand-mark"><img src="${logo()}" alt="FAFATRAINING"></span><span class="brand-copy">FAFATRAINING<small>COACH STUDIO</small></span></button><div class="top-actions">${utilities}</div></header>${body}<div id="modalHost"></div></main><nav class="dock" aria-label="Navigation principale"><button class="${active==='home'?'on':''}" data-go="home">⌂<span>Accueil</span></button><button class="${active==='clients'?'on':''}" data-go="clients">◎<span>Adhérents</span></button><button class="${active==='create'?'on':''}" data-go="create">＋<span>Créer</span></button><button class="${active==='plans'?'on':''}" data-go="plans">◫<span>Plans</span></button><button class="${active==='library'?'on':''}" data-go="library">▦<span>Mouvements</span></button></nav><button class="timer-fab ${TIMER.running?'running':''}" data-open-timer aria-label="Ouvrir le timer"><span>⏱</span><b id="timerFabText">${safe(timerDisplayLabel())}</b></button>`}
function timerTotalV94(){return TIMER.mode==='interval'?TIMER.rounds*(TIMER.work+TIMER.rest)-TIMER.rest:0}
function openTimerModal(){$('#modalHost').innerHTML=`<div class="modal-bg"><section class="modal timer-modal v94-timer"><button class="modal-x" data-close-modal>×</button><p class="eyebrow">TIMER COACH</p><div class="segmented timer-modes"><button class="${TIMER.mode==='interval'?'on':''}" data-timer-mode="interval">Intervalles</button><button class="${TIMER.mode==='stopwatch'?'on':''}" data-timer-mode="stopwatch">Chrono libre</button></div><div id="timerBig" class="timer-big">${safe(timerDisplayLabel())}</div>${TIMER.mode==='interval'?`<div class="timer-presets"><button data-timer-preset="20:10:8">20/10 × 8</button><button data-timer-preset="30:15:10">30/15 × 10</button><button data-timer-preset="40:20:8">40/20 × 8</button><button data-timer-preset="45:15:10">45/15 × 10</button><button data-timer-preset="60:30:6">60/30 × 6</button></div><div class="timer-fields"><label><small>TRAVAIL</small><div class="timer-stepper"><button type="button" data-timer-step="work:-5" ${TIMER.running?'disabled':''}>−</button><span><input id="timerWork" type="number" min="5" step="5" value="${TIMER.work}" ${TIMER.running?'disabled':''}><b>s</b></span><button type="button" data-timer-step="work:5" ${TIMER.running?'disabled':''}>+</button></div></label><label><small>REPOS</small><div class="timer-stepper"><button type="button" data-timer-step="rest:-5" ${TIMER.running?'disabled':''}>−</button><span><input id="timerRest" type="number" min="0" step="5" value="${TIMER.rest}" ${TIMER.running?'disabled':''}><b>s</b></span><button type="button" data-timer-step="rest:5" ${TIMER.running?'disabled':''}>+</button></div></label><label><small>TOURS</small><div class="timer-stepper"><button type="button" data-timer-step="rounds:-1" ${TIMER.running?'disabled':''}>−</button><span><input id="timerRounds" type="number" min="1" value="${TIMER.rounds}" ${TIMER.running?'disabled':''}><b>×</b></span><button type="button" data-timer-step="rounds:1" ${TIMER.running?'disabled':''}>+</button></div></label></div><div id="timerSummary" class="timer-summary"><b>RÉGLAGES ACTIFS</b><span>${TIMER.work}s travail · ${TIMER.rest}s repos · ${TIMER.rounds} tours · ≈ ${fmtTime(timerTotalV94())}</span></div><button class="btn ghost huge timer-apply" data-timer-apply ${TIMER.running?'disabled':''}>✓ Valider et préparer le timer</button>`:'<p class="timer-help">Chronomètre libre pour séries, récupérations, tests ou temps de passage.</p>'}<div class="timer-actions"><button class="btn primary" data-timer-start>${TIMER.running?'Pause':'Démarrer'}</button><button class="btn ghost" data-timer-reset>Réinitialiser</button></div><p class="timer-help">Le timer continue si tu fermes cette fenêtre ou changes d’écran.</p></section></div>`;bindModal();bindV91();bindV94();updateTimerUI()}
function applyTimerSettingsV94(resetPhase=true){if(TIMER.mode!=='interval')return;let w=Math.max(5,Number($('#timerWork')?.value)||TIMER.work),r=Math.max(0,Number($('#timerRest')?.value)||0),rounds=Math.max(1,Number($('#timerRounds')?.value)||TIMER.rounds);TIMER.work=w;TIMER.rest=r;TIMER.rounds=rounds;if(resetPhase&&!TIMER.running){TIMER.phase='work';TIMER.round=1;TIMER.remaining=TIMER.work}saveTimer();updateTimerUI();let s=$('#timerSummary');if(s)s.innerHTML=`<b>RÉGLAGES ACTIFS</b><span>${TIMER.work}s travail · ${TIMER.rest}s repos · ${TIMER.rounds} tours · ≈ ${fmtTime(timerTotalV94())}</span>`}
function startPauseTimerV94(){if(TIMER.mode==='interval'){if(!TIMER.running){applyTimerSettingsV94(true);TIMER.endAt=Date.now()+TIMER.remaining*1000;TIMER.running=true}else{TIMER.remaining=Math.max(0,Math.ceil((TIMER.endAt-Date.now())/1000));TIMER.running=false}}else{if(TIMER.running){TIMER.elapsed+=Math.floor((Date.now()-TIMER.startedAt)/1000);TIMER.running=false;TIMER.startedAt=0}else{TIMER.running=true;TIMER.startedAt=Date.now()}}saveTimer();ensureTimerLoop();openTimerModal()}
function bindV94(){
 $$('[data-program-family-v93]').forEach(x=>x.onclick=()=>{programFilter.family=x.dataset.programFamilyV93;programFilter.type='Tous';renderKeepScroll()});
 $$('[data-program-type-v94]').forEach(x=>x.onclick=()=>{programFilter.type=x.dataset.programTypeV94;renderKeepScroll()});
 $$('[data-program-equipment-v94]').forEach(x=>x.onclick=()=>{programFilter.equipment=x.dataset.programEquipmentV94;renderKeepScroll()});
 $('[data-program-reset]')?.addEventListener('click',()=>{programFilter={q:'',family:'Tous',level:'Tous',equipment:'Tous',type:'Tous'};render()});
 $('[data-timer-apply]')?.addEventListener('click',()=>{applyTimerSettingsV94(true);toast('Timer prêt avec ces réglages')});
 $('[data-timer-start]')?.addEventListener('click',startPauseTimerV94);
 $$('[data-timer-preset]').forEach(x=>x.onclick=()=>{if(TIMER.running)return;let [w,r,n]=x.dataset.timerPreset.split(':').map(Number);let a=$('#timerWork'),b=$('#timerRest'),c=$('#timerRounds');if(a)a.value=w;if(b)b.value=r;if(c)c.value=n;applyTimerSettingsV94(true);openTimerModal()});
 $$('[data-timer-step]').forEach(x=>x.onclick=()=>{if(TIMER.running)return;let [kind,delta]=x.dataset.timerStep.split(':'),map={work:['#timerWork',5],rest:['#timerRest',0],rounds:['#timerRounds',1]},[sel,min]=map[kind],el=$(sel);if(!el)return;el.value=Math.max(min,(Number(el.value)||min)+Number(delta));applyTimerSettingsV94(true)});
 ['#timerWork','#timerRest','#timerRounds'].forEach(sel=>$(sel)?.addEventListener('input',()=>{if(TIMER.running)return;applyTimerSettingsV94(true)}));
}
function bind(){bindLegacyCore();bindV91();bindV93();bindV94()}

boot();
